pub fn charge_outline(control: &mut dyn WorkControl, units: usize) -> Result<()> {
    control
        .charge(
            WorkKind::Media,
            u64::try_from(units).map_err(|_| Diagnostic {
                kind: ErrorKind::Limit(LimitKind::Arithmetic),
                offset: 0,
            })?,
